#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_TERMS 200

int main(int argc, char **argv)
{
    if (argc < 3) {
        puts("NO_INPUT");
        return 0;
    }

    char *end1, *end2;
    long a = strtol(argv[1], &end1, 10);
    long b = strtol(argv[2], &end2, 10);

    if (end1 == argv[1] || *end1 != '\0' || end2 == argv[2] || *end2 != '\0') {
        puts("BAD_INPUT");
        return 0;
    }

    long terms[MAX_TERMS];
    int count = 0;
    long num = a;
    long den = b;

    while (den != 0 && count < MAX_TERMS) {
        long q = num / den;
        terms[count++] = q;
        long r = num - q * den;
        num = den;
        den = r;
    }

    putchar('[');
    if (count > 0) {
        printf("%ld", terms[0]);
        if (count > 1) {
            printf("; %ld", terms[1]);
            for (int i = 2; i < count; ++i) {
                printf(", %ld", terms[i]);
            }
        }
    }
    putchar(']');
    putchar('\n');
    return 0;
}
